const { delegateToSchema } = require('@graphql-tools/delegate');
const express = require('express');
const { createHandler } = require('graphql-http/lib/use/express');
const { makeExecutableSchema } = require('@graphql-tools/schema');
const db = require('../db');

const app = express();
app.use(express.json());

const resolvers = {
  Mutation: {
    updateDeliveryAddress: async (parent, { shipmentId, newAddress }, context, info) => {
      // Validate that the shipment is owned by the authenticated user
      const shipment = await db('customer_shipments')
        .where({ id: shipmentId, customer_id: context.user.id })
        .first();
      if (!shipment) {
        throw new Error('Shipment not found or unauthorized');
      }

      return delegateToSchema({
        schema: context.logisticsSubschema,
        operation: 'mutation',
        fieldName: 'modifyDestination',
        args: { shipmentId, address: newAddress },
        context,
        info
      });
    }
  }
};

const schema = makeExecutableSchema({ typeDefs: require('./schemaDefs'), resolvers });
app.all('/graphql', createHandler({ schema }));
module.exports = app;
